e":"Injeção eletrônica PGM-FI","unit":"text","source":0},"transmission":{"value":"Manual de cinco marchas","unit":"text","source":0},"clutch":{"value":"Multidisco em banho de óleo, acionamento por cabo","unit":"text","source":0},"finalDrive":{"value":"Corrente, passo 428","unit":"text","source":0},"frontSuspension":{"value":"Telescópica, tubos de 33 mm, curso de roda 120 mm","unit":"text","source":0},"rearSuspension":{"value":"Dois amortecedores, curso de roda 106 mm","unit":"text","source":0},"brakeSystem":{"value":"CBS (frenagem combinada)","unit":"text","source":0},"frontDiscSize":{"value":240,"unit":"mm","source":0},"frontTyre":{"value":"80/100-18, sem câmara","unit":"text","source":0},"rearTyre":{"value":"100/80-18, sem câmara","unit":"text","source":0},"wheels":{"value":"Liga leve","unit":"text","source":0},"tubeless":{"value":"Sim; dianteiro e traseiro","unit":"text","source":0},"lighting":{"value":"Lanterna traseira LED; farol não especificado nesta fonte","unit":"text","source":0},"panel":{"value":"Digital, indicador de marcha e computador de bordo","unit":"text","source":0}},"sources":[],"change_note":"Lote 01: complementação com fonte verificável e escopo Brasil; dados originais preservados."}]$data$::jsonb)
      AS p(variant_id uuid, specifications jsonb, sources jsonb, change_note text)
  LOOP
    SELECT v.revision INTO current_revision
      FROM motorcycle_catalog_variants v WHERE v.id = patch.variant_id FOR UPDATE;
    IF current_revision IS NULL OR current_revision <> 1 THEN
      RAISE EXCEPTION 'Catalogo inicial inesperado para %; revisao atual %',patch.variant_id,current_revision;
    END IF;
    SELECT r.specifications,r.sources INTO previous_specs,previous_sources
      FROM motorcycle_catalog_revisions r
      WHERE r.variant_id=patch.variant_id AND r.revision=1 AND r.status='reviewed';
    IF previous_specs IS NULL THEN
      RAISE EXCEPTION 'Revisao 1 reviewed ausente para %',patch.variant_id;
    END IF;
    SELECT array_agg(field.key) INTO conflicts
      FROM jsonb_object_keys(patch.specifications) AS field(key)
      WHERE previous_specs ? field.key;
    IF conflicts IS NOT NULL THEN
      RAISE EXCEPTION 'Campos anteriores nao podem ser substituidos em %: %',patch.variant_id,conflicts;
    END IF;
    IF jsonb_array_length(previous_sources) <> 1 THEN
      RAISE EXCEPTION 'Numero de fontes iniciais nao esperado para %',patch.variant_id;
    END IF;
    INSERT INTO motorcycle_catalog_revisions
      (variant_id,revision,specifications,sources,status,change_note)
      VALUES (patch.variant_id,2,previous_specs || patch.specifications,
              previous_sources || patch.sources,'reviewed',patch.change_note);
    UPDATE motorcycle_catalog_variants SET revision=2 WHERE id=patch.variant_id;
    n:=n+1;
  END LOOP;
  IF n<>7 THEN RAISE EXCEPTION 'Esperados 7 modelos/versoes; obtidos %',n; END IF;
END
$migrate$;
